hotspots=[{'x':67,'y':60,'title':'Oil filler','text':'The blue filler cap is on the rocker cover. Use the specified oil; filling here does not measure the oil level.'},{'x':66.4,'y':51.5,'title':'Coolant pressure cap','text':'The pressure cap is on the cooling assembly. Only inspect or open as directed with the engine safely cooled.'},{'x':79,'y':47,'title':'Alternator','text':'The alternator is driven by a belt and generates electrical power while running. Inspect its belt only with the engine stopped.'},{'x':70,'y':76,'title':'Rigid injection lines','text':'These lines carry high-pressure fuel towards the injectors in the cylinder head. Keep clear of pressure leaks; do not loosen them as a beginner.'},{'x':44,'y':36,'title':'Remote fuel filter / separator','text':'This unit is mounted away from the engine. Locate the filters and shutoff valve on your own installation using its documentation.'}]
d={'hotspots':hotspots,'lessons':[dict(id=f'de{i+1}',title=t,art=a,lead=l,points=p,example=e,remember=r) for i,(t,a,l,p,e,r) in enumerate(lessons)],'quiz':quiz,'faults':faults,'sources':sources,'photos':photos,'checklist':['Correct engine and gearbox manuals available','Engine and gearbox fluid levels checked by their own methods','Coolant checked safely with engine cool','Enough usable fuel and intended fuel supply available','No fresh fuel, oil, coolant or seawater leaks','Cooling seacock and strainer checked for normal operation afloat','Belt and hoses inspected with engine stopped','Battery/start settings checked; boat secure and control in neutral','Crew, clothing and tools clear of moving parts','After starting: normal cooling discharge and instruments checked']}
(R/'libraries/project-watch/diesel-1.98.0.js').write_text('/* Original recreational diesel teaching and question bank. Reviewed 29 September 2026. */\nwindow.PW_DIESEL='+json.dumps(d,ensure_ascii=False,indent=2)+';\n')
# Exact, original vector teaching: principles, not claimed model layouts.
def text(x,y,s,size=24,color='#173a44',weight=400,anchor='start'):
 return f'<text x="{x}" y="{y}" font-size="{size}" fill="{color}" font-weight="{weight}" text-anchor="{anchor}">{html.escape(s)}</text>'
def rect(x,y,w,h,fill='#fff',stroke='#c4cec7',rx=16):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" fill="{fill}" stroke="{stroke}" stroke-width="2"/>'
def line(x,y,u,v,color='#287b99',width=6):return f'<path d="M{x} {y}L{u} {v}" fill="none" stroke="{color}" stroke-width="{width}" marker-end="url(#arrow)"/>'
def label(x,y,t,sub=''):
 return text(x,y,t,25,weight=700)+text(x,y+34,sub,20,'#526c70')
def plate(name,title,subtitle,body,foot='Original principle diagram • actual layout and servicing depend on the model'):
 s=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1440 900" role="img" aria-labelledby="title desc"><title id="title">{html.escape(title)}</title><desc id="desc">{html.escape(subtitle)}</desc><defs><linearGradient id="metal"><stop stop-color="#6c8588"/><stop offset=".4" stop-color="#e2e9e6"/><stop offset=".65" stop-color="#b7c7c7"/><stop offset="1" stop-color="#516c73"/></linearGradient><linearGradient id="brass"><stop stop-color="#73521d"/><stop offset=".42" stop-color="#e5c478"/><stop offset="1" stop-color="#8c6931"/></linearGradient><linearGradient id="oil"><stop stop-color="#edd698"/><stop offset="1" stop-color="#b78135"/></linearGradient><marker id="arrow" markerWidth="10" markerHeight="10" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="context-stroke"/></marker></defs><rect width="1440" height="900" fill="#f5f2e9"/><g font-family="Arial,Helvetica,sans-serif">{text(60,52,'PROJECT WATCH / DIESEL ENGINE BASICS',17,'#5c7778',700)}{text(60,109,title,38,weight=700)}{text(60,152,subtitle,23,'#526c70')}{body}{text(60,858,foot,19,'#526c70')}</g></svg>'''
 (A/(name+'.svg')).write_text(s)
# Overview: systems, not invented realistic engine geometry.
b=''
for i,(title,sub,detail,c) in enumerate([('FUEL','Clean diesel, delivered correctly','Tank → filters → injection','#bd852e'),('AIR','Air in; exhaust out','Ventilation and sound exhaust','#597e67'),('COOLING','Heat out of the engine','Coolant + seawater circuits','#287b99'),('LUBRICATION','Protect moving parts','Specified oil, level and pressure','#a4773a'),('STARTING','Turn the engine to start','Battery, cables and starter','#526b9b'),('DRIVE','Power to the propeller','Gearbox and shaft / saildrive','#6b7178')]):
 x=60+(i%3)*450;y=218+(i//3)*280
 b+=rect(x,y,420,235)+f'<circle cx="{x+52}" cy="{y+53}" r="25" fill="{c}"/>'+text(x+52,y+61,str(i+1),22,'#fff',700,'middle')+text(x+95,y+62,title,27,weight=700)+text(x+28,y+128,sub,22)+text(x+28,y+178,detail,20,'#526c70')
plate('overview','Six systems. One reliable engine.','Learn the jobs first, then locate the actual parts in your manual.',b)
# Four strokes: intake valve open/closed; injector near TDC; arrows correct.
