for i,(title,caption,py,up,intake,exhaust) in enumerate([('1  INTAKE','Air drawn into cylinder',528,False,True,False),('2  COMPRESSION','Air squeezed and heated',355,True,False,False),('3  POWER','Burning gas pushes down',465,False,False,False),('4  EXHAUST','Burned gas expelled',355,True,False,True)]):
 x=48+i*348;b+=rect(x,208,326,572)+text(x+24,252,title,25,weight=700)
 b+=f'<path d="M{x+57} 321V653H{x+273}V321" fill="#e1e8e3" stroke="#687f83" stroke-width="14"/><rect x="{x+69}" y="326" width="192" height="326" fill="#fff"/><rect x="{x+69}" y="326" width="192" height="{py-326}" fill="{["#d8eaf2","#f2d9aa","#f5c08a","#d4d7d8"][i]}"/>'
 b+=f'<rect x="{x+64}" y="{py}" width="202" height="58" rx="5" fill="url(#metal)" stroke="#566a6e" stroke-width="3"/><path d="M{x+70} {py+12}H{x+260}M{x+70} {py+23}H{x+260}" stroke="#566a6e" stroke-width="4"/><path d="M{x+165} {py+58}V675" stroke="url(#metal)" stroke-width="22"/>'
 # head and valves; intake on left, exhaust right
