 for dx,opened in [(102,intake),(225,exhaust)]:
  vy=343 if opened else 315;b+=f'<path d="M{x+dx} 283V{vy}" stroke="#526c70" stroke-width="8"/><path d="M{x+dx-18} {vy}H{x+dx+18}" stroke="#526c70" stroke-width="8"/>'
 b+=f'<path d="M{x+165} 282V334" stroke="#b28c48" stroke-width="12"/>'
 if i==0:b+=line(x+8,350,x+91,374)
 if i==3:b+=line(x+229,370,x+310,308,'#727c80')
